test('all nine WebAudio entry points restore actual stopped output gain and retain zero-volume intent',async()=>{const actions=[h=>h.engine.play(samplePlan()),h=>h.engine.play(samplePlan(),{voice:'clean-synth'}),h=>h.engine.play(samplePlan(),{voice:'violin-sample'}),h=>h.engine.reference(440),h=>h.engine.metronome(80),h=>h.engine.chord('C'),h=>h.engine.playStringNote('A4'),h=>h.engine.stringChord('Am'),h=>h.engine.playLoops([{...loopRow('a',0,1),blob:new Blob([sampleBytes()],{type:'audio/wav'})}])];for(const action of actions){const h=sampleHarness();await h.engine.ready();h.engine.setEffects({volume:.47});h.engine.stop();assert.equal(h.engine.status().outputGain,0);await action(h);assert.equal(h.engine.status().outputGain,.47);assert.ok(h.engine.status().activeVoices>0||h.engine.status().loops>0);h.engine.stop();assert.equal(h.engine.status().outputGain,0);assert.equal(h.engine.status().activeVoices,0);assert.equal(h.intervals.size,0);await h.engine.dispose();const muted=sampleHarness();muted.engine.setEffects({volume:0});await assert.rejects(action(muted),{code:'OUTPUT_MUTED'});assert.equal(muted.engine.status().effects.volume,0);assert.equal(muted.engine.status().muted,true);assert.equal(muted.contexts.length,0);assert.equal(muted.requests.length,0);await muted.engine.dispose();}});
test('output RMS excludes real microphone meter and does not claim signal from a muted or suspended output',async()=>{const h=harness();h.engine.setEffects({volume:0});const capture=await h.engine.startCapture('microphone');assert.equal(h.permissions(),1);const output=h.contexts[0].nodes.find(node=>node.type==='analyser');output.level=.125;capture.meter.level=.75;assert.equal(h.engine.getLevel(),.75);assert.equal(h.engine.status().outputRms,0);h.engine.setEffects({volume:.65});assert.equal(h.engine.status().outputRms,.125);h.contexts[0].state='suspended';assert.equal(h.engine.getOutputLevel(),0);await capture.stop();await h.engine.dispose();});
test('disposing a pending browser unlock cancels its wait and removes the resume deadline',async()=>{const h=harness({resume:()=>new Promise(()=>{})}),pending=h.engine.unlock(),rejection=assert.rejects(pending,{code:'DISPOSED'});assert.equal(h.timers.size,1);await h.engine.dispose();await rejection;assert.equal(h.timers.size,0);assert.equal(h.intervals.size,0);assert.equal(h.engine.status().ready,false);});
test('context interruption clears real schedulers, voices and loops then explicit playback can recover',async()=>{const h=harness(),failures=[];await h.engine.play(samplePlan(),{onError:error=>failures.push(error.code)});await h.engine.metronome(80);await h.engine.chord('C');await h.engine.playLoops([loopRow('a',0,1)]);const ctx=h.contexts[0];ctx.emitState('suspended');const state=h.engine.status();for(const field of ['playing','metronome','chord'])assert.equal(state[field],false);for(const field of ['loops','activeVoices','outputGain'])assert.equal(state[field],0);assert.equal(state.error.code,'AUDIO_INTERRUPTED');assert.deepEqual(failures,['AUDIO_INTERRUPTED']);assert.equal(h.intervals.size,0);await h.engine.reference(440);assert.equal(h.engine.status().state,'running');assert.equal(h.engine.status().outputGain,.65);assert.equal(h.engine.status().error,null);await h.engine.dispose();assert.equal([...ctx.listeners.values()].reduce((sum,set)=>sum+set.size,0),0);});
test('locked resume fails within a deadline without leaving a graph, voice, timer or fake success',async()=>{const h=harness({resume:()=>new Promise(()=>{})}),pending=h.engine.unlock(),rejection=assert.rejects(pending,{code:'AUDIO_UNLOCK_REQUIRED'});const timer=[...h.timers.values()].find(timer=>timer.ms===8000);assert.ok(timer);timer.fn();await rejection;assert.equal(h.engine.status().ready,false);assert.equal(h.contexts[0].state,'closed');assert.equal(h.engine.status().error.code,'AUDIO_UNLOCK_REQUIRED');assert.equal(h.timers.size,0);assert.equal(h.voices().length,0);await h.engine.dispose();});
test('optional AudioSession requests playback for sound, automatic mic routing, and restores prior ownership',async()=>{const h=harness(),listeners=new Set(),session={type:'ambient',state:'active',addEventListener(type,fn){listeners.add(fn);},removeEventListener(type,fn){listeners.delete(fn);}};h.environment.navigator.audioSession=session;await h.engine.reference(440);assert.equal(session.type,'playback');const capture=await h.engine.startCapture('microphone');assert.equal(session.type,'auto');await h.engine.reference(440);assert.equal(session.type,'auto');await capture.stop();await h.engine.reference(440);assert.equal(session.type,'playback');session.state='interrupted';for(const fn of listeners)fn();assert.equal(h.engine.status().activeVoices,0);assert.equal(h.engine.status().error.code,'AUDIO_INTERRUPTED');await h.engine.dispose();assert.equal(session.type,'ambient');assert.equal(listeners.size,0);await assert.rejects(h.engine.unlock(),{code:'DISPOSED'});assert.equal(session.type,'ambient');});
test('unsupported audio sessions cannot block sound or clobber another owner on disposal',async()=>{const h=harness();h.environment.navigator.audioSession={get type(){return 'auto';},set type(value){throw Error('unsupported');},get state(){return 'inactive';}};await h.engine.reference(440);assert.ok(h.voices().length);await h.engine.dispose();const other=harness(),session={type:'ambient',state:'active'};other.environment.navigator.audioSession=session;await other.engine.reference(440);session.type='transient';await other.engine.dispose();assert.equal(session.type,'transient');});
test('construction and parameter choices never request microphone or start audio without an explicit action',async()=>{const h=harness();h.engine.setPreset('Warm');h.engine.setEffects({volume:.5,reverb:.3});h.engine.setInputGain(1.4);assert.equal(h.contexts.length,0);assert.equal(h.permissions(),0);assert.equal(h.engine.status().state,'not-started');await h.engine.dispose();assert.equal(h.contexts.length,0);assert.equal(h.intervals.size,0);});
test('interactive context latency statistics come from the real context fields and do not imply Bluetooth latency',async()=>{const h=harness();await h.engine.ready();assert.equal(h.contexts[0].options.latencyHint,'interactive');assert.equal(h.engine.status().baseLatency,.007);assert.equal(h.engine.status().outputLatency,.013);assert.equal(h.permissions(),0);await h.engine.dispose();assert.equal(h.contexts[0].state,'closed');});
test('ready failure closes the failed graph and a subsequent explicit attempt can recover',async()=>{let attempts=0;const h=harness({resume:async()=>{if(++attempts===1)throw new Error('audio permission gate');}});await assert.rejects(h.engine.ready(),{code:'AUDIO_START_FAILED'});assert.equal(h.contexts[0].state,'closed');assert.ok(h.contexts[0].nodes.filter(n=>n.type!=='destination').every(n=>n.connections.size===0));await h.engine.ready();assert.equal(h.contexts.length,2);assert.equal(h.engine.status().state,'running');await h.engine.dispose();});
test('string notes synthesize original harmonics in the allowed violin range with velocity-dependent amplitude',async()=>{const h=harness();await h.engine.playStringNote('G3','sustain',.1);const first=h.voices()[0];assert.ok(Math.abs(first.frequency.value-195.9977)<.001);assert.equal(first.wave.real[0],0);assert.ok(first.wave.imag[1]>0&&first.wave.imag[2]>0);assert.ok(first.connections.size>0);const lowPeak=Math.max(...first.context.nodes.filter(n=>n.type==='gain').flatMap(n=>n.gain.events.filter(e=>e.method==='linear').map(e=>e.value)));h.engine.stop();await h.engine.playStringNote('A4','short',1);const a=h.voices()[0];assert.equal(a.frequency.value,440);assert.ok(a.context.nodes.filter(n=>n.type==='gain').some(n=>n.gain.events.some(e=>e.method==='linear'&&e.value>lowPeak)));h.engine.stop();await h.engine.playStringNote('E7','pluck',.7);assert.ok(Math.abs(h.voices()[0].frequency.value-2637.020)<.002);await h.engine.dispose();assert.equal(h.voices().length,0);});
test('invalid note range, unsupported style and nonfinite/low velocity reject before audio starts',async()=>{const h=harness();for(const args of [['E3'],['F7'],['B7'],['A2'],['H4'],['A4','legato'],['A4','short',NaN],['A4','short',.09],['A4','pluck',1.1]])await assert.rejects(h.engine.playStringNote(...args),{code:'INVALID_VALUE'});assert.equal(h.contexts.length,0);assert.equal(h.permissions(),0);});
test('string polyphony is bounded and stop releases all voices so another note can start',async()=>{const h=harness();for(let i=0;i<24;i++)await h.engine.playStringNote('A4','short',.5);await assert.rejects(h.engine.playStringNote('A4','short',.5),{code:'VOICE_LIMIT'});assert.equal(h.voices().length,24);h.engine.stop();assert.equal(h.voices().length,0);assert.equal((await h.engine.playStringNote('D4')).started,true);await h.engine.dispose();});
test('stopping while an audio resume is pending cancels a new string note',async()=>{let release;const h=harness({resume:()=>new Promise(resolve=>release=resolve)}),pending=h.engine.playStringNote('A4');h.engine.stop();release();assert.equal((await pending).cancelled,true);assert.equal(h.voices().length,0);await h.engine.dispose();});
test('stop and ready restore output routing without leaving old voices or timers',async()=>{const h=harness();await h.engine.play([{start:0,end:1,freq:440}]);h.engine.stop();assert.equal(h.intervals.size,0);assert.equal(h.voices().length,0);const output=h.contexts[0].nodes.find(n=>n.type==='gain'&&[...n.connections].some(t=>t.type==='analyser'));assert.equal(output.gain.value,0);await h.engine.ready();assert.equal(output.gain.value,.65);await h.engine.dispose();});
test('string chord stop removes chord timer and all sounding string voices',async()=>{const h=harness();await h.engine.stringChord('C','sustain',80,.65);assert.equal(h.intervals.size,1);assert.equal(h.voices().length,3);h.engine.stopChord();assert.equal(h.intervals.size,0);assert.equal(h.voices().length,0);await h.engine.dispose();});
test('arpeggiated major seventh chord visits every chord tone instead of dropping the fourth',async()=>{const h=harness();await h.engine.stringChord('Cmaj7','pluck',120,.7);const pitches=[];for(let i=0;i<4;i++){pitches.push(h.contexts[0].nodes.filter(n=>n.kind==='oscillator').at(-1).frequency.value);h.advance(.5);h.tick();}const unique=new Set(pitches.map(v=>Math.round(12*Math.log2(v/440)+69)));assert.deepEqual([...unique].sort((a,b)=>a-b),[60,64,67,71]);await h.engine.dispose();});
test('an audio-context failure during a chord stops its scheduler and releases voices',async()=>{const h=harness();await h.engine.stringChord('Am','short',80,.5);h.contexts[0].state='closed';h.advance(1);h.tick();assert.equal(h.engine.status().chord,false);assert.equal(h.intervals.size,0);assert.equal(h.voices().length,0);assert.equal(h.engine.status().error.code,'STRINGS_FAILED');await h.engine.dispose();});
test('microphone digital gain records the processed destination, not raw input, without speaker feedback',async()=>{const h=harness();h.engine.setInputGain(.5);const capture=await h.engine.startCapture('microphone'),ctx=h.contexts[0],source=ctx.nodes.find(n=>n.type==='media-source'),gain=capture.inputGain,destination=ctx.nodes.find(n=>n.type==='media-destination');assert.equal(h.permissions(),1);assert.equal(source.stream,h.raw);assert.notEqual(h.recorders[0].stream,h.raw);assert.equal(h.recorders[0].stream,destination.stream);assert.ok(source.connections.has(gain));assert.ok(gain.connections.has(destination));assert.ok(gain.connections.has(capture.meter));assert.equal(gain.gain.value,.5);assert.equal(gain.connections.has(ctx.destination),false);h.engine.setInputGain(2);assert.equal(gain.gain.value,2);capture.meter.level=.1;assert.ok(h.engine.getLevel()>.09&&h.engine.getLevel()<.11);h.advance(1.25);const result=await capture.stop();assert.equal(result.source,'microphone');assert.equal(result.duration,1.25);assert.ok(result.blob.size>0);assert.equal(h.raw.track.stops>0,true);assert.equal(destination.stream.track.stops>0,true);assert.equal(source.connections.size,0);assert.equal(gain.connections.size,0);assert.equal(capture.meter.connections.size,0);assert.equal(h.engine.status().captures,0);await h.engine.dispose();});
test('digital gain validates bounds and updates all active microphone captures',async()=>{const h=harness();for(const value of [-1,2.01,NaN,'1',Infinity])assert.throws(()=>h.engine.setInputGain(value),{code:'INVALID_VALUE'});const first=await h.engine.startCapture('microphone'),second=await h.engine.startCapture('microphone');h.engine.setInputGain(0);assert.equal(first.inputGain.gain.value,0);assert.equal(second.inputGain.gain.value,0);await Promise.all([first.stop(),second.stop()]);await h.engine.dispose();});
test('device failures show a localized cause and keep the browser text for diagnostics',async()=>{const h=harness({getUserMedia:async()=>{throw Object.assign(new Error('Requested device not found'),{name:'NotFoundError'});}});await assert.rejects(h.engine.startCapture('microphone'),e=>e.code==='CAPTURE_START_FAILED'&&/没有找到可用的输入设备/.test(e.message)&&!/Requested device/.test(e.message)&&e.causeMessage==='Requested device not found');await h.engine.dispose();});
test('microphone permission rejection leaves no recorder, stream graph or timers',async()=>{const h=harness({getUserMedia:async()=>{throw Object.assign(new Error('denied'),{name:'NotAllowedError'});}});await assert.rejects(h.engine.startCapture('microphone'),{code:'CAPTURE_START_FAILED'});assert.equal(h.recorders.length,0);assert.equal(h.engine.status().captures,0);assert.equal(h.contexts[0].nodes.filter(n=>n.type==='media-source').length,0);await h.engine.dispose();assert.equal(h.intervals.size,0);assert.equal(h.timers.size,0);});
test('dispose cancels a late microphone permission grant and closes all granted tracks',async()=>{let release;const h=harness({getUserMedia:()=>new Promise(resolve=>release=resolve)}),pending=h.engine.startCapture('microphone');for(let i=0;i<5&&!release;i++)await flush();assert.ok(release);await h.engine.dispose();release(h.raw);await assert.rejects(pending,{code:'CANCELLED'});assert.ok(h.raw.track.stops>0);assert.equal(h.recorders.length,0);assert.equal(h.contexts[0].state,'closed');assert.equal(h.intervals.size,0);assert.equal(h.timers.size,0);});
test('synth recording uses the output destination and disconnects it after completion',async()=>{const h=harness(),capture=await h.engine.startCapture('synth'),ctx=h.contexts[0],destination=ctx.nodes.find(n=>n.type==='media-destination');const output=ctx.nodes.find(n=>n.type==='gain'&&n.connections.has(destination));assert.ok(output);assert.equal(h.recorders[0].stream,destination.stream);assert.equal(h.permissions(),0);await capture.stop();assert.equal(output.connections.has(destination),false);assert.ok(destination.stream.track.stops>0);await h.engine.dispose();});
test('empty audio blobs fail instead of reporting completed media',async()=>{const h=harness({empty:true}),capture=await h.engine.startCapture('microphone');await assert.rejects(capture.stop(),{code:'EMPTY_CAPTURE'});assert.equal(h.engine.status().captures,0);assert.ok(h.raw.track.stops>0);await h.engine.dispose();});
test('MediaRecorder error and construction/start failures close microphone and processed tracks',async()=>{const h=harness(),capture=await h.engine.startCapture('microphone');h.recorders[0].onerror({error:new Error('encoder failed')});await assert.rejects(capture.stop(),{code:'CAPTURE_FAILED'});assert.ok(h.raw.track.stops>0);assert.equal(h.engine.status().captures,0);await h.engine.dispose();for(const config of [{recorderConstructorFailure:true},{recorderStartFailure:true}]){const f=harness(config);await assert.rejects(f.engine.startCapture('microphone'));assert.ok(f.raw.track.stops>0);assert.equal(f.engine.status().captures,0);assert.ok(f.contexts[0].nodes.filter(n=>n.type==='media-source'||n.type==='media-destination').every(n=>n.connections.size===0));await f.engine.dispose();}});
test('audio capture uses periodic chunks and a duration limit stops and completes a real media blob',async()=>{const h=harness({options:{maxCaptureDurationMs:1000}}),capture=await h.engine.startCapture('microphone');assert.equal(h.recorders[0].timeslice,1000);const deadline=[...h.timers.values()].find(t=>t.ms===1000);assert.ok(deadline);h.advance(1);deadline.fn();const result=await capture.finished;assert.equal(result.duration,1);assert.ok(result.blob.size>0);assert.equal(h.timers.size,0);assert.equal(h.engine.status().captures,0);assert.ok(h.raw.track.stops>0);await h.engine.dispose();});
test('audio capture byte limit rejects an incomplete file and releases processing and input tracks',async()=>{const h=harness({options:{maxCaptureBytes:20}}),capture=await h.engine.startCapture('microphone');h.recorders[0].ondataavailable({data:new Blob(['12345678901234567890'])});h.recorders[0].ondataavailable({data:new Blob(['x'])});await assert.rejects(capture.finished,{code:'CAPTURE_FAILED'});assert.match(h.engine.status().error.message,/大小上限/);assert.equal(h.engine.status().captures,0);assert.equal(h.timers.size,0);assert.ok(h.raw.track.stops>0);assert.ok(h.recorders[0].stream.track.stops>0);await h.engine.dispose();});
test('audio stop timeout fails and dispose completes after the bounded recording deadline',async()=>{const h=harness({neverStops:true,options:{captureStopTimeoutMs:50}}),capture=await h.engine.startCapture('microphone');const pending=h.engine.dispose();const deadline=[...h.timers.values()].find(t=>t.ms===50);assert.ok(deadline);deadline.fn();await assert.rejects(capture.finished,{code:'CAPTURE_FAILED'});await pending;assert.match(h.engine.status().error.message,/超时/);assert.equal(h.engine.status().captures,0);assert.equal(h.timers.size,0);assert.equal(h.contexts[0].state,'closed');assert.ok(h.raw.track.stops>0);});
test('invalid recording limits reject before requesting permissions or creating processing resources',async()=>{for(const options of [{maxCaptureDurationMs:1800001},{maxCaptureBytes:0},{captureStopTimeoutMs:10001}]){const h=harness({options});await assert.rejects(h.engine.startCapture('microphone'),{code:'INVALID_VALUE'});assert.equal(h.permissions(),0);assert.equal(h.engine.status().captures,0);assert.equal(h.recorders.length,0);assert.equal(h.contexts.length,0);await h.engine.dispose();}});
const loopRow=(id,index,duration)=>{const bytes=new ArrayBuffer(8);new DataView(bytes).setFloat64(0,duration);return {id,kind:'loop',completed:true,trackIndex:index,blob:new Blob([bytes],{type:'audio/webm'})};};
test('real loop buffers start on one audio clock, volume/mutes work, stop releases source nodes',async()=>{const h=harness();const result=await h.engine.playLoops([loopRow('a',0,1),loopRow('b',1,1.5)],[.6,.8],[false,true]);assert.equal(result.started,true);const sources=h.contexts[0].nodes.filter(n=>n.type==='buffer-source');assert.equal(sources.length,2);assert.equal(sources[0].startAt,sources[1].startAt);assert.equal(sources[0].loopEnd,1);assert.equal(sources[1].loopEnd,1.5);assert.equal([...sources[0].connections][0].gain.value,.6);assert.equal([...sources[1].connections][0].gain.value,0);h.engine.setLoopLevels([.2,.3],[true,false]);assert.equal([...sources[0].connections][0].gain.value,0);assert.equal([...sources[1].connections][0].gain.value,.3);h.engine.stopLoops();assert.equal(h.engine.status().loops,0);assert.ok(sources.every(n=>n.connections.size===0&&n.stopCalls===1));await h.engine.dispose();});
test('loop decode failure and cancellation never start partially decoded sources',async()=>{const bad=harness({decode:async()=>{throw new Error('unsupported audio');}});await assert.rejects(bad.engine.playLoops([loopRow('a',0,1)]),{code:'DECODE_FAILED'});assert.equal(bad.contexts[0].nodes.filter(n=>n.type==='buffer-source').length,0);await bad.engine.dispose();let release;const h=harness({decode:()=>new Promise(resolve=>release=resolve)}),pending=h.engine.playLoops([loopRow('a',0,1)]);for(let i=0;i<5&&!release;i++)await flush();h.engine.stopLoops();release(h.contexts[0].createBuffer(1,8000,8000));assert.equal((await pending).cancelled,true);assert.equal(h.contexts[0].nodes.filter(n=>n.type==='buffer-source').length,0);await h.engine.dispose();});
test('aligned loops pad and trim copies to two seconds without changing original audio or shifting attacks',async()=>{const originals=[];const h=harness({decode:async(bytes,ctx)=>{const duration=new DataView(bytes).getFloat64(0),buffer=ctx.createBuffer(1,duration*ctx.sampleRate,ctx.sampleRate);buffer.getChannelData(0).fill(duration===1?.25:.75);buffer.getChannelData(0).fill(0,0,10);originals.push(buffer);return buffer;}});const result=await h.engine.playLoops([loopRow('short',0,1),loopRow('long',1,3)],[],[],{alignLength:true,bpm:120,meter:'4/4',barCount:1});assert.equal(result.alignedDuration,2);const sources=h.contexts[0].nodes.filter(n=>n.type==='buffer-source');assert.equal(sources[0].startAt,sources[1].startAt);assert.equal(sources[0].loopEnd,2);assert.equal(sources[1].loopEnd,2);assert.equal(sources[0].buffer.length,16000);assert.equal(sources[0].buffer.getChannelData(0)[9],0);assert.equal(sources[0].buffer.getChannelData(0)[10],.25);assert.equal(sources[0].buffer.getChannelData(0)[7999],.25);assert.equal(sources[0].buffer.getChannelData(0)[8000],0);assert.equal(sources[1].buffer.getChannelData(0)[15999],.75);assert.equal(originals[0].length,8000);assert.equal(originals[1].length,24000);assert.equal(originals[1].getChannelData(0)[23999],.75);assert.notEqual(sources[0].buffer,originals[0]);await h.engine.dispose();});
test('aligned 6/8 loops use quarter-note BPM and the selected number of bars',async()=>{const h=harness(),result=await h.engine.playLoops([loopRow('a',0,.5)],[],[],{alignLength:true,bpm:120,meter:'6/8',barCount:2});assert.equal(result.alignedDuration,3);assert.equal(h.contexts[0].nodes.find(n=>n.type==='buffer-source').loopEnd,3);await h.engine.dispose();});
test('invalid alignment tempo, meter or bar count fails without starting source nodes',async()=>{for(const settings of [{bpm:29,meter:'4/4',barCount:1},{bpm:120,meter:'0/4',barCount:1},{bpm:120,meter:'4/3',barCount:1},{bpm:120,meter:'4/4',barCount:1.5},{bpm:120,meter:'4/4',barCount:129}]){const h=harness();await assert.rejects(h.engine.playLoops([loopRow('a',0,1)],[],[],{alignLength:true,...settings}),{code:'INVALID_VALUE'});assert.equal(h.contexts[0].nodes.filter(n=>n.type==='buffer-source').length,0);assert.equal(h.engine.status().loops,0);await h.engine.dispose();}});
test('alignment rejects durations over 120 seconds and output copies over the sample budget',async()=>{const h=harness();await assert.rejects(h.engine.playLoops([loopRow('a',0,1)],[],[],{alignLength:true,bpm:30,meter:'4/4',barCount:16}),{code:'LOOP_RESOURCE_LIMIT'});assert.equal(h.engine.status().loops,0);await h.engine.dispose();const heavy=harness({sampleRate:48000,decode:async(_,ctx)=>ctx.createBuffer(2,4800,48000)});await assert.rejects(heavy.engine.playLoops([0,1,2,3].map(i=>loopRow('n'+i,i,.1)),[],[],{alignLength:true,bpm:32,meter:'4/4',barCount:16}),{code:'LOOP_RESOURCE_LIMIT'});assert.equal(heavy.contexts[0].nodes.filter(n=>n.type==='buffer-source').length,0);await heavy.engine.dispose();});
test('alignment cancellation during decoding does not allocate or start the playback copy',async()=>{let release;const h=harness({decode:()=>new Promise(resolve=>release=resolve)}),pending=h.engine.playLoops([loopRow('a',0,1)],[],[],{alignLength:true,bpm:120,meter:'4/4',barCount:1});for(let i=0;i<5&&!release;i++)await flush();h.engine.stopLoops();release(h.contexts[0].createBuffer(1,8000,8000));const result=await pending;assert.equal(result.cancelled,true);assert.equal(h.contexts[0].nodes.filter(n=>n.type==='buffer-source').length,0);assert.equal(h.engine.status().loops,0);await h.engine.dispose();});
