test('loop byte contents are rechecked instead of trusting a caller-supplied Blob size',async()=>{let calls=0;const h=harness({decode:async(_,ctx)=>{calls++;return ctx.createBuffer(1,8000,8000);}}),row={...loopRow('a',0,1),blob:{size:1,arrayBuffer:async()=>new ArrayBuffer(16*1024*1024+1)}};await assert.rejects(h.engine.playLoops([row]),{code:'LOOP_RESOURCE_LIMIT'});assert.equal(calls,0);assert.equal(h.contexts[0].nodes.filter(n=>n.type==='buffer-source').length,0);await h.engine.dispose();});
