test('ending a raw microphone finalizes its processed recording only after the final encoder chunk',async()=>{
  const h=harness({neverStops:true}),capture=await h.engine.startCapture('microphone'),recorder=h.recorders[0];let completed=false;
  capture.finished.then(()=>completed=true);h.advance(1.25);h.raw.track.end();await flush();
  assert.equal(recorder.stopCalls,1);assert.equal(completed,false);assert.equal(h.engine.status().captures,1);
  recorder.ondataavailable({data:new Blob(['final audio'],{type:recorder.mimeType})});recorder.onstop();
  const result=await capture.finished;assert.equal(result.duration,1.25);assert.equal(await result.blob.text(),'final audio');
  assert.equal(h.engine.status().captures,0);assert.equal(h.timers.size,0);assert.equal(h.raw.track.listeners.get('ended').size,0);
  assert.equal(recorder.stream.track.readyState,'ended');await capture.stop();assert.equal(recorder.stopCalls,1);await h.engine.dispose();
});

test('a microphone that ended before its grant cannot start a silent processed recording',async()=>{
  const h=harness({getUserMedia:async(_,raw)=>{raw.track.readyState='ended';return raw;}});
  await assert.rejects(h.engine.startCapture('microphone'),{code:'MISSING_TRACK'});
  assert.equal(h.recorders.length,0);assert.equal(h.engine.status().captures,0);assert.equal(h.timers.size,0);
  assert.ok(h.raw.track.stops>0);assert.equal(h.contexts[0].nodes.some(n=>n.type==='media-source'),false);await h.engine.dispose();
});

test('context interruption finalizes existing microphone and synth takes without silent tails or automatic resume',async()=>{
  for(const source of ['microphone','synth'])for(const state of ['interrupted','suspended']){
    const h=harness(),capture=await h.engine.startCapture(source);h.advance(.75);h.contexts[0].emitState(state);
    const result=await capture.finished;assert.equal(result.duration,.75);assert.ok(result.blob.size>0);
    assert.equal(h.recorders[0].stopCalls,1);assert.equal(h.engine.status().captures,0);assert.equal(h.timers.size,0);
    assert.equal(h.engine.status().state,state);assert.equal(h.engine.status().error.code,'AUDIO_INTERRUPTED');
    await h.engine.reference(440);assert.equal(h.engine.status().state,'running');assert.equal(h.engine.status().error,null);await h.engine.dispose();
  }
});

test('an interrupted AudioSession finalizes a take even when no playback voice is active',async()=>{
  const h=harness(),listeners=new Set(),session={type:'ambient',state:'active',addEventListener(_,fn){listeners.add(fn);},removeEventListener(_,fn){listeners.delete(fn);}};
  h.environment.navigator.audioSession=session;const capture=await h.engine.startCapture('microphone');h.advance(2);
  assert.equal(h.engine.status().activeVoices,0);session.state='interrupted';for(const fn of [...listeners])fn();
  const result=await capture.finished;assert.equal(result.duration,2);assert.ok(result.blob.size>0);assert.equal(h.engine.status().captures,0);
  assert.equal(h.engine.status().error.code,'AUDIO_INTERRUPTED');await h.engine.dispose();assert.equal(listeners.size,0);
});

test('interrupted captures still reject missing final media and encoder timeout instead of saving empty success',async()=>{
  const empty=harness({empty:true}),take=await empty.engine.startCapture('microphone');empty.contexts[0].emitState('interrupted');
  await assert.rejects(take.finished,{code:'EMPTY_CAPTURE'});assert.equal(empty.engine.status().captures,0);assert.equal(empty.timers.size,0);await empty.engine.dispose();
  const late=harness({neverStops:true,options:{captureStopTimeoutMs:50}}),pending=await late.engine.startCapture('microphone');late.contexts[0].emitState('suspended');
  const deadline=[...late.timers.values()].find(t=>t.ms===50);assert.ok(deadline);deadline.fn();
  await assert.rejects(pending.finished,{code:'CAPTURE_FAILED'});assert.equal(late.engine.status().captures,0);assert.equal(late.timers.size,0);assert.equal(late.raw.track.listeners.get('ended').size,0);await late.engine.dispose();
});

test('a synchronous audio encoder stop during start does not leave a duration timer or input listener',async()=>{
  const h=harness();h.environment.MediaRecorder.prototype.start=function(){this.state='inactive';this.ondataavailable({data:new Blob(['short take'],{type:this.mimeType})});this.onstop();};
  const capture=await h.engine.startCapture('microphone'),result=await capture.finished;
  assert.equal(await result.blob.text(),'short take');assert.equal(h.engine.status().captures,0);assert.equal(h.timers.size,0);assert.equal(h.raw.track.listeners.get('ended').size,0);await h.engine.dispose();
});

test('a synchronous audio encoder error during start rejects without a dangling take or timer',async()=>{
  const h=harness();h.environment.MediaRecorder.prototype.start=function(){this.state='recording';this.onerror({error:Error('encoder could not start')});};
  await assert.rejects(h.engine.startCapture('microphone'),{code:'CAPTURE_FAILED'});
  assert.equal(h.engine.status().captures,0);assert.equal(h.timers.size,0);assert.equal(h.raw.track.listeners.get('ended').size,0);assert.ok(h.raw.track.stops>0);await h.engine.dispose();
});

test('successful capture settlement is independent of previous or concurrent playback errors',async()=>{
  for(const concurrent of [false,true]){
    const h=harness();h.engine.setEffects({volume:0});await assert.rejects(h.engine.reference(440),{code:'OUTPUT_MUTED'});
    let unrelated;h.environment.MediaRecorder.prototype.start=function(){
      if(concurrent){unrelated=h.engine.reference(440);unrelated.catch(()=>{});}
      this.state='inactive';this.ondataavailable({data:new Blob(['valid microphone take'],{type:this.mimeType})});this.onstop();
    };
    const capture=await h.engine.startCapture('microphone'),result=await capture.finished;
    assert.equal(await result.blob.text(),'valid microphone take');assert.equal(h.engine.status().captures,0);assert.equal(h.timers.size,0);
    if(concurrent){await assert.rejects(unrelated,{code:'OUTPUT_MUTED'});assert.equal(h.engine.status().error.code,'OUTPUT_MUTED');}
    await h.engine.dispose();
  }
});

test('audio capture negotiates MP4-only recorders and respects browser defaults without MIME probing',async()=>{
  for(const probe of [type=>type==='audio/mp4',undefined]){
    const h=harness();h.environment.MediaRecorder.isTypeSupported=probe;const capture=await h.engine.startCapture('microphone'),result=await capture.stop();
    assert.equal(result.mime,probe?'audio/mp4':'audio/webm');assert.ok(result.blob.size>0);assert.equal(h.timers.size,0);await h.engine.dispose();
  }
});

const sampleRoot=new URL('../dist/assets/audio/violin/',import.meta.url),sampleManifest=JSON.parse(fs.readFileSync(new URL('manifest.json',sampleRoot),'utf8'));
const sampleBytes=(note='A4')=>{const buffer=fs.readFileSync(new URL(note+'.wav',sampleRoot));return buffer.buffer.slice(buffer.byteOffset,buffer.byteOffset+buffer.byteLength);};
const samplePlan=(freq=440,extra={})=>[{start:0,end:1,freq,...extra}];
function decodeSample(bytes,ctx){const view=new DataView(bytes),frames=view.getUint32(40,true)/2,buffer=ctx.createBuffer(1,frames,view.getUint32(24,true)),data=buffer.getChannelData(0);for(let index=0;index<frames;index++)data[index]=view.getInt16(44+index*2,true)/32768;return buffer;}
function sampleHarness(config={}){const requests=[];const h=harness({decode:decodeSample,...config,options:{fetch:async(url,options)=>{requests.push({url,options});const note=/\/([AE][3-6])\.wav$/.exec(url)?.[1];return {ok:true,arrayBuffer:async()=>sampleBytes(note)};},...config.options}});return {...h,requests};}
test('seven CC0 sample files have exact hashes, bounded real PCM content and a complete provenance manifest',()=>{
  assert.equal(sampleManifest.license,'CC0-1.0');assert.equal(sampleManifest.commit,'440300901dfe9275fd84e0b7763af1f8443ae62e');assert.equal(sampleManifest.samples.length,7);let total=0;
  for(const sample of sampleManifest.samples){const bytes=fs.readFileSync(new URL(sample.file,sampleRoot));total+=bytes.length;assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),sample.sha256);assert.equal(bytes.length,sample.bytes);assert.equal(bytes.toString('ascii',0,4),'RIFF');assert.equal(bytes.toString('ascii',8,12),'WAVE');assert.equal(bytes.readUInt32LE(4),bytes.length-8);assert.equal(bytes.readUInt16LE(20),1);assert.equal(bytes.readUInt16LE(22),1);assert.equal(bytes.readUInt32LE(24),22050);assert.equal(bytes.readUInt16LE(34),16);assert.equal(bytes.readUInt32LE(40),sample.frames*2);let energy=0,peak=0;for(let offset=44;offset<bytes.length;offset+=2){const value=bytes.readInt16LE(offset)/32768;energy+=value*value;peak=Math.max(peak,Math.abs(value));}assert.ok(Math.sqrt(energy/sample.frames)>.005,sample.note+' must contain audio');assert.ok(peak>.1&&peak<.81);assert.ok(sample.loopStart>0&&sample.loopEnd<sample.duration&&sample.loopStart<sample.loopEnd);}
  assert.equal(total,sampleManifest.totalWavBytes);assert.ok(total<1000000);const license=fs.readFileSync(new URL('LICENSE.txt',sampleRoot));assert.equal(crypto.createHash('sha256').update(license).digest('hex'),sampleManifest.licenseSha256);assert.match(license.toString(),/CC0/);
});
