test('stop cancels an unresolved sample fetch promptly and never starts a late response',async()=>{let resolve;const h=sampleHarness({options:{fetch:()=>new Promise(done=>resolve=done)}}),pending=h.engine.play(samplePlan(),{voice:'violin-sample'});for(let i=0;i<5&&!resolve;i++)await flush();h.engine.stop();assert.equal((await pending).cancelled,true);assert.equal(h.engine.status().sampleLoading,0);resolve({ok:true,arrayBuffer:async()=>sampleBytes()});await flush();assert.equal(h.engine.status().sampleBuffers,0);assert.equal(h.contexts[0].nodes.some(node=>node.kind==='buffer-source'),false);assert.equal(h.timers.size,0);await h.engine.dispose();});
test('stop during decode prevents cache publication and disposal closes a waiting request',async()=>{let resolve;const h=sampleHarness({decode:()=>new Promise(done=>resolve=done)}),pending=h.engine.play(samplePlan(),{voice:'violin-sample'});for(let i=0;i<5&&!resolve;i++)await flush();assert.ok(resolve);h.engine.stop();assert.equal((await pending).cancelled,true);resolve(h.contexts[0].createBuffer(1,61740,22050));await flush();assert.equal(h.engine.status().sampleBuffers,0);assert.equal(h.contexts[0].nodes.some(node=>node.kind==='buffer-source'),false);await h.engine.dispose();let started=false;const closing=sampleHarness({options:{fetch:()=>{started=true;return new Promise(()=>{});}}}),late=closing.engine.play(samplePlan(),{voice:'violin-sample'});for(let i=0;i<5&&!started;i++)await flush();await closing.engine.dispose();assert.equal((await late).cancelled,true);assert.equal(closing.contexts[0].state,'closed');assert.equal(closing.timers.size,0);assert.equal(closing.engine.status().sampleBuffers,0);});
test('switching from a loading sample voice to clean synthesis invalidates old work and preserves new playback',async()=>{let resolve;const h=sampleHarness({options:{fetch:()=>new Promise(done=>resolve=done)}}),old=h.engine.play(samplePlan(),{voice:'violin-sample'});for(let i=0;i<5&&!resolve;i++)await flush();await h.engine.play(samplePlan(660),{voice:'clean-synth'});assert.equal((await old).cancelled,true);resolve({ok:true,arrayBuffer:async()=>sampleBytes()});await flush();assert.equal(h.engine.status().playing,true);assert.equal(h.engine.status().demoVoice,'clean-synth');assert.equal(h.voices().at(-1).frequency.value,660);assert.equal(h.engine.status().sampleBuffers,0);await h.engine.dispose();});
test('unknown demo voices and invalid sample velocity reject before fetching or starting audio',async()=>{const h=sampleHarness();await assert.rejects(h.engine.play(samplePlan(),{voice:'fake-violin'}),{code:'INVALID_VALUE'});for(const velocity of [0,128,NaN,1.5,'90'])await assert.rejects(h.engine.play(samplePlan(440,{velocity}),{voice:'violin-sample'}),{code:'INVALID_PLAN'});assert.equal(h.requests.length,0);assert.equal(h.contexts.length,0);});
test('stopping before audio is ready never downloads samples and stop aborts a live network signal',async()=>{let release;const h=sampleHarness({resume:()=>new Promise(resolve=>release=resolve)}),pending=h.engine.play(samplePlan(),{voice:'violin-sample'});h.engine.stop();release();assert.equal((await pending).cancelled,true);assert.equal(h.requests.length,0);await h.engine.dispose();let signal;const live=sampleHarness({options:{AbortController,fetch:async(url,options)=>{signal=options.signal;return new Promise(()=>{});}}}),loading=live.engine.play(samplePlan(),{voice:'violin-sample'});for(let i=0;i<5&&!signal;i++)await flush();assert.ok(signal);assert.equal(signal.aborted,false);live.engine.stop();assert.equal(signal.aborted,true);assert.equal((await loading).cancelled,true);await live.engine.dispose();});
test('failed sample requests are retryable and never poison the decoded cache',async()=>{let good=false,calls=0;const h=sampleHarness({options:{fetch:async()=>{calls++;return {ok:good,arrayBuffer:async()=>sampleBytes()};}}});await assert.rejects(h.engine.play(samplePlan(),{voice:'violin-sample'}),{code:'SAMPLE_LOAD_FAILED'});good=true;await h.engine.play(samplePlan(),{voice:'violin-sample'});assert.equal(calls,2);assert.equal(h.engine.status().sampleBuffers,1);assert.equal(h.engine.status().playing,true);assert.equal(h.engine.status().error,null);await h.engine.dispose();});
test('sample polyphony is bounded and scheduler failure releases every partially started source',async()=>{const h=sampleHarness(),plan=Array.from({length:65},()=>({start:0,end:1,freq:440}));await assert.rejects(h.engine.play(plan,{voice:'violin-sample'}),{code:'VOICE_LIMIT'});const sources=h.contexts[0].nodes.filter(node=>node.kind==='buffer-source');assert.equal(sources.length,64);assert.ok(sources.every(node=>node.connections.size===0));assert.equal(h.intervals.size,0);assert.equal(h.engine.status().playing,false);await h.engine.play(samplePlan(),{voice:'violin-sample'});assert.equal(h.engine.status().playing,true);await h.engine.dispose();});
